<script setup lang="ts">
const api = useApi(); const form = reactive({ email: '' }); const token = ref(''); const sent = ref(false); const loading = ref(false)
async function submit() { loading.value = true; try { const r = await api.request<any>('/auth/forgot', { method: 'POST', body: form }); token.value = r.resetToken || ''; sent.value = true } finally { loading.value = false } }
</script>
<template><section class="section-y"><div class="wrap max-w-md"><p class="label-mono text-signal-deep">Account recovery</p><h1 class="type-product-hero mt-2">Reset your password.</h1><p class="mt-2 text-[12px] text-ink/75">Enter the account email. In demo mode the reset link is shown directly.</p><form class="mt-6 space-y-4" @submit.prevent="submit"><div><label class="field-label">Email</label><input v-model="form.email" type="email" required class="field"></div><button class="btn btn-dark w-full" :disabled="loading">{{ loading ? 'Sending…' : 'Send reset link' }}</button></form><div v-if="sent" class="mt-4 rounded-lg border border-ink/12 bg-bone p-4"><p class="text-[12px]">If the account exists, a reset link was created.</p><NuxtLink v-if="token" :to="`/reset?token=${token}`" class="mt-2 inline-block font-mono text-[10px] uppercase text-signal-deep">Open reset link →</NuxtLink></div><NuxtLink to="/login" class="mt-5 inline-block text-[11px] text-ink/75">← Back to sign in</NuxtLink></div></section></template>
